from connectDB import get_connection, load_config

# Execute a SQL query generated by the LLM
# Returns the data as a list of dicts where each dict represents a tuple in the dataset
def execute_sql(query):
    conn = get_connection()
    cur = conn.cursor()
    try: 
        cur.execute(query)
        columns = [desc[0] for desc in cur.description]     
        return [dict(zip(columns, row)) for row in cur.fetchall()]      
    except Exception as e: 
        return f"SQL error: {e}"
    finally: 
        cur.close()
        conn.close()

